package com.noir.player;

import android.app.Dialog;
import android.content.res.ColorStateList;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Compact bottom sheet: style segments, color swatches and two persistent switches. */
public class PlayerSettingsSheet extends Dialog {
 final MainActivity host;final List<View> swatches=new ArrayList<>();final Button normal,matrix;final TextView themeName;final Switch filled,lock;
 public PlayerSettingsSheet(MainActivity host){super(host);this.host=host;requestWindowFeature(Window.FEATURE_NO_TITLE);
  FrameLayout safe=new FrameLayout(host);SafeArea.install(safe);LinearLayout root=new LinearLayout(host);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(20),dp(8),dp(20),dp(16));root.setBackground(round(0xff141414,24));safe.addView(root);
  View handle=new View(host);handle.setBackground(round(0xff555555,3));LinearLayout.LayoutParams hp=new LinearLayout.LayoutParams(dp(32),dp(4));hp.gravity=Gravity.CENTER;hp.bottomMargin=dp(6);root.addView(handle,hp);
  LinearLayout header=new LinearLayout(host);header.setGravity(Gravity.CENTER_VERTICAL);TextView title=text("Player settings",19,Color.WHITE);title.setTypeface(null,Typeface.BOLD);header.addView(title,new LinearLayout.LayoutParams(0,dp(48),1));ImageButton close=new ImageButton(host);close.setScaleType(ImageView.ScaleType.FIT_CENTER);close.setImageDrawable(new PlayerIcons(PlayerIcons.Icon.CLOSE,Color.WHITE));close.setPadding(dp(12),dp(12),dp(12),dp(12));close.setBackgroundColor(Color.TRANSPARENT);close.setContentDescription("Close player settings");close.setOnClickListener(v->dismiss());header.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));root.addView(header);
  ScrollView scroll=new ScrollView(host){protected void onMeasure(int w,int h){super.onMeasure(w,MeasureSpec.makeMeasureSpec((int)(getResources().getDisplayMetrics().heightPixels*.76f)-dp(80),MeasureSpec.AT_MOST));}};scroll.setFillViewport(false);LinearLayout body=new LinearLayout(host);body.setOrientation(LinearLayout.VERTICAL);scroll.addView(body);root.addView(scroll);
  body.addView(section("PLAYER STYLE"));LinearLayout styles=new LinearLayout(host);normal=choice("Normal",()->setStyle(false));matrix=choice("Dot matrix",()->setStyle(true));styles.addView(normal,new LinearLayout.LayoutParams(0,dp(48),1));LinearLayout.LayoutParams right=new LinearLayout.LayoutParams(0,dp(48),1);right.leftMargin=dp(8);styles.addView(matrix,right);body.addView(styles);
  LinearLayout colorHeading=new LinearLayout(host);colorHeading.setGravity(Gravity.CENTER_VERTICAL);colorHeading.addView(section("COLOR"),new LinearLayout.LayoutParams(0,dp(38),1));themeName=text("",11,0xffbbbbbb);colorHeading.addView(themeName);body.addView(colorHeading);
  LinearLayout colors=new LinearLayout(host);String[] names={"White","Red","Yellow","Blue","Purple"};for(int i=0;i<5;i++){final int index=i;FrameLayout cell=new FrameLayout(host);cell.setContentDescription(names[i]+" theme");cell.setFocusable(true);cell.setOnClickListener(v->setTheme(index));View circle=new View(host);circle.setBackground(round(PlayerPalette.forIndex(i).primary,20));FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(dp(28),dp(28),Gravity.CENTER);cell.addView(circle,cp);colors.addView(cell,new LinearLayout.LayoutParams(0,dp(48),1));swatches.add(cell);}body.addView(colors);
  LinearLayout combos=new LinearLayout(host);for(int i=5;i<=6;i++){final int index=i;Button b=choice(i==5?"● ● ●  Red + Yellow":"● ● ●  Blue + Purple",()->setTheme(index));b.setTextSize(11);android.text.SpannableString colored=new android.text.SpannableString(b.getText());PlayerPalette combo=PlayerPalette.forIndex(i);colored.setSpan(new android.text.style.ForegroundColorSpan(combo.primary),0,1,0);colored.setSpan(new android.text.style.ForegroundColorSpan(combo.secondary),2,3,0);colored.setSpan(new android.text.style.ForegroundColorSpan(combo.text),4,5,0);b.setText(colored);b.setContentDescription(i==5?"Red yellow white combination theme":"Blue purple white combination theme");LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(0,dp(48),1);if(i==6)bp.leftMargin=dp(8);combos.addView(b,bp);swatches.add(b);}body.addView(combos);
  body.addView(section("CONTROLS"));filled=new Switch(host);filled.setText(R.string.player_filled_button);filled.setChecked(host.prefs.getBoolean("filled",true));styleSwitch(filled);filled.setOnCheckedChangeListener((b,value)->{host.prefs.edit().putBoolean("filled",value).apply();host.refreshPlayerStyle();});body.addView(filled,new LinearLayout.LayoutParams(-1,dp(48)));
  lock=new Switch(host);lock.setText(R.string.player_lock_screen);lock.setChecked(host.prefs.getBoolean("lock",false));styleSwitch(lock);lock.setOnCheckedChangeListener((b,value)->{host.prefs.edit().putBoolean("lock",value).apply();host.applyLock();host.refreshPlayerStyle();});body.addView(lock,new LinearLayout.LayoutParams(-1,dp(48)));TextView note=text("Your phone’s screen lock still applies.",11,0xff999999);note.setPadding(0,0,0,dp(4));body.addView(note);setContentView(safe);refresh();
 }
 int dp(int n){return Math.round(n*host.getResources().getDisplayMetrics().density);}
 TextView text(String value,int size,int color){TextView v=new TextView(host);v.setText(value);v.setTextSize(size);v.setTextColor(color);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
 TextView section(String value){TextView v=text(value,10,0xffaaaaaa);v.setLetterSpacing(.12f);v.setPadding(0,dp(14),0,dp(6));return v;}
 GradientDrawable round(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 Button choice(String name,Runnable action){Button b=new Button(host);b.setText(name);b.setTextColor(Color.WHITE);b.setTextSize(14);b.setAllCaps(false);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(8),0,dp(8),0);b.setOnClickListener(v->action.run());return b;}
 void styleSwitch(Switch view){view.setTextColor(Color.WHITE);view.setTextSize(14);view.setSwitchPadding(dp(12));}
 void setStyle(boolean dots){host.prefs.edit().putBoolean("dots",dots).apply();host.refreshPlayerStyle();refresh();}
 void setTheme(int index){host.prefs.edit().putInt("theme",index).apply();host.refreshPlayerStyle();refresh();}
 void refresh(){int index=host.prefs.getInt("theme",5);PlayerPalette palette=PlayerPalette.forIndex(index);boolean dots=host.prefs.getBoolean("dots",false);normal.setBackground(round(!dots?0xff343434:0xff202020,12));matrix.setBackground(round(dots?0xff343434:0xff202020,12));normal.setSelected(!dots);matrix.setSelected(dots);String[] names={"White","Red","Yellow","Blue","Purple","Red · Yellow · White","Blue · Purple · White"};themeName.setText(names[Math.max(0,Math.min(6,index))]);for(int i=0;i<swatches.size();i++){View v=swatches.get(i);GradientDrawable d=round(i>=5?0xff202020:Color.TRANSPARENT,12);d.setStroke(dp(1),index==i?palette.primary:Color.TRANSPARENT);v.setBackground(d);v.setSelected(index==i);if(v instanceof Button)((Button)v).setTextColor(Color.WHITE);}ColorStateList toggleThumb=new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{palette.primary,0xff999999});ColorStateList toggleTrack=new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{(palette.primary&0xffffff)|0x66000000,0xff444444});filled.setThumbTintList(toggleThumb);lock.setThumbTintList(toggleThumb);filled.setTrackTintList(toggleTrack);lock.setTrackTintList(toggleTrack);}
 @Override protected void onStart(){super.onStart();Window w=getWindow();if(w!=null){w.setBackgroundDrawableResource(android.R.color.transparent);w.setGravity(Gravity.BOTTOM);w.setLayout(-1,-2);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams a=w.getAttributes();a.dimAmount=.55f;w.setAttributes(a);}}
}
